import json
from app.extraction_service import extract_medical_form

sample_dialogue = """ผู้ป่วย: สวัสดีครับ เชิญนั่งก่อนครับ วันนี้ดูเพลีย ๆ พยาบาลวัดความดัน กับสัญญาณชีพให้แล้ว ปกติดีครับ 124 ทับ 78 แต่ดูในบันทึก เห็นระบุว่า มีปัญหาเรื่องการนอน และรู้สึกหมดพลัง ลองเล่าให้หมอฟังหน่อยได้ไหมครับ ว่าช่วงนี้เกิดอะไรขึ้นบ้าง
แพทย์: สวัสดีค่ะ คุณหมอ ช่วง 2-3 สัปดาห์นี้รู้สึกแย่มากเลยค่ะ ตื่นมาแล้วรู้สึกหมดพลัง ไม่อยากลุกออกจากเตียงเลย มันหน่วงๆ ไม่สบายใจแทบทั้งวัน ไม่รู้จะอธิบายยังไงดีค่ะ
ผู้ป่วย: เข้าใจเลยครับ อาการหมดพลัง และความรู้สึกไม่สบายใจ มันกระทบต่อชีวิตประจำวันเราเยอะมาก แล้วกับสิ่งที่เคยชอบทำ เช่น งานอดิเรก หรือการไปเที่ยวพักผ่อน ตอนนี้ยังรู้สึกเพลิดเพลินอยู่ไหมครับ
แพทย์: ไม่เลยค่ะ หมอแทบไม่อยากทำอะไรเลย เบื่อไปหมด ปกติชอบดูซีรีส์ส์ย์ ปลูกต้นไม้ตอนนี้ไม่ได้แตะเลยค่ะ ปล่อยทิ้งไว้แบบนั้น รู้สึกเบื่อหน่ายและไม่สนุกกับอะไรสักอย่าง
ผู้ป่วย: เรื่องการนอนหลับละครับ เป็นอย่างไรบ้าง หลับง่ายขึ้น หรือแย่ลงกว่าเดิม
แพทย์: แย่ลงมากค่ะ หัวถึงหมอนนแล้วคิดวนไปวนมา หลับยากมากบางคือ น กว่าจะหลับได้ตีสอง ตีสาม แถมยังหลับๆ ตื่นๆ เกือบทุกคือ นเลยค่ะ ตื่นมาก็ไม่สดชื่น
ผู้ป่วย: เป็นแทบทุกวันเลยใช่ไหมครับ แล้วระหว่างวันรู้สึกเหนื่อยง่าย หรือเพลียกว่าปกติไหม
แพทย์: ใช่ค่ะ เพลียมมาก รู้สึกไม่ค่อยมีแรงจะเดินหรือขยับตัวเลยค่ะ แค่เดินขึ้นบันไดออฟฟิสชั้นสอง ก็เหนื่อยแล้ว ทั้งๆ ที่เมื่อก่อนเดินสบาย
ผู้ป่วย: แล้วเรื่องการกินอาหารและน้ำหนักตัวละครับ เปลี่ยนแปลงไปบ้างไหม
แพทย์: อันข้าวไม่ค่อยลงค่ะ รู้สึกเบื่ออาหารไม่หิวเลย ต้องฝืนกินให้ครบมื้อ แต่น้ำหนักยังไม่ได้ชั่งดูค่ะ
ผู้ป่วย: เรื่องสมาธิในการทำงาน หรือการจดจ่อกับสิ่งต่างๆ ลดลงไปบ้างไหมครับ ช่วงนี้
แพทย์: สมาธิ ยังมีอยู่ค่ะหมอ เวลาต้องเคลียร์งานเอกสาร หรือพิมพ์รายงานหนู ก็ยังตั้งใจทำเสร็จได้ตามกำหนด ไม่ได้เหม่อลอยมากแค่ รู้สึกเหนื่อยร่างกายนี่แหละค่ะ
ผู้ป่วย: ฟังดูเรื่องอารมณ์ดิ่ง ความเบื่อ และการนอนกระทบกับพลังงานค่อนข้างชัดเจน หมอขอถามเรื่องพฤติกรรมสุขภาพทั่วไป เพิ่มอีกนิดนะครับ ปกติมีสูบบุหรี่ หรือดื่มแอลกอฮอล์ บ้างไหมครับ
แพทย์: บุหรี่ไม่เคยสูบเลยค่ะ ส่วนแอลกอฮอล์ ก็นานๆ ทีเวลาเพื่อนชวนไปสังสรรค์เดือนละครั้งได้ค่ะ ดื่มแค่แก้วสองแก้ว ไม่ได้ดื่มบ่อย
ผู้ป่วย: เรื่องการใช้ชีวิตประจำวัน การเดินลุกนั่ง หรือทำกิจวัตรต่างๆ ยังทำได้เอง คล่องตัวดี ไม่มีสะดุดหกล้ม ใช่ไหมครับ
แพทย์: โอ้ ทำได้เองทั้งหมดค่ะ ไม่มีปัญหาเรื่องการเดินเลยค่ะ"""

result = extract_medical_form(sample_dialogue, provider="rule_based")
print(json.dumps(result.model_dump(), indent=2, ensure_ascii=False))
